import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Sistem Jaminan Satu Jalan untuk Semua","description":"","frontmatter":{},"headers":[],"relativePath":"id/08-人人有路保障体系.md","filePath":"id/08-人人有路保障体系.md","lastUpdated":null}'),u={name:"id/08-人人有路保障体系.md"};function s(r,a,d,k,l,m){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="sistem-jaminan-satu-jalan-untuk-semua" tabindex="-1">Sistem Jaminan Satu Jalan untuk Semua <a class="header-anchor" href="#sistem-jaminan-satu-jalan-untuk-semua" aria-label="Permalink to &quot;Sistem Jaminan Satu Jalan untuk Semua&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>08</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Satu Jalan untuk Semua, Sistem Jaminan, Garis Dasar Evolusi, Kelompok Rentan, Universal</td></tr></tbody></table><h2 id="i-definisi-dasar-satu-jalan-untuk-semua" tabindex="-1">I. Definisi Dasar Satu Jalan untuk Semua <a class="header-anchor" href="#i-definisi-dasar-satu-jalan-untuk-semua" aria-label="Permalink to &quot;I. Definisi Dasar Satu Jalan untuk Semua&quot;">​</a></h2><p>Satu jalan untuk semua adalah salah satu tujuan sosial inti Peradaban Simbiosis Jangkar, yang berarti memastikan bahwa setiap kehidupan di Heng Yuan Zhou, terlepas dari ras, asal-usul, bakat, tingkat, atau kondisi kekayaannya, dapat memperoleh jalur evolusi yang cocok untuk dirinya sendiri, dan memiliki kesempatan untuk mencapai peningkatan tingkat dan penyempurnaan kehidupan melalui usahanya sendiri. &quot;Memiliki jalan&quot; tidak hanya berarti memiliki metode latihan untuk dipelajari, tetapi juga memiliki sumber daya untuk digunakan, mentor untuk bertanya, lingkungan untuk berlatih, dan institusi untuk diandalkan.</p><p>Satu jalan untuk semua dan lebih banyak kerja lebih banyak imbalan adalah dua pilar sistem distribusi peradaban simbiosis. Lebih banyak kerja lebih banyak imbalan menyelesaikan masalah &quot;efisiensi&quot;, mendorong yang kuat untuk menciptakan lebih banyak nilai; satu jalan untuk semua menyelesaikan masalah &quot;keadilan&quot;, memastikan yang lemah tidak ditinggalkan oleh sistem evolusi. Keduanya saling melengkapi, dan tidak ada yang lengkap tanpa yang lain. Tanpa satu jalan untuk semua, lebih banyak kerja lebih banyak imbalan akan merosot menjadi hukum rimba; tanpa lebih banyak kerja lebih banyak imbalan, satu jalan untuk semua akan merosot menjadi egalitarianisme.</p><h2 id="ii-kebutuhan-akan-satu-jalan-untuk-semua" tabindex="-1">II. Kebutuhan akan Satu Jalan untuk Semua <a class="header-anchor" href="#ii-kebutuhan-akan-satu-jalan-untuk-semua" aria-label="Permalink to &quot;II. Kebutuhan akan Satu Jalan untuk Semua&quot;">​</a></h2><p>Pembentukan sistem jaminan satu jalan untuk semua didasarkan pada pemahaman mendalam berikut:</p><h3 id="_2-1-hak-evolusi-adalah-hak-hidup-yang-paling-dasar" tabindex="-1">2.1 Hak evolusi adalah hak hidup yang paling dasar <a class="header-anchor" href="#_2-1-hak-evolusi-adalah-hak-hidup-yang-paling-dasar" aria-label="Permalink to &quot;2.1 Hak evolusi adalah hak hidup yang paling dasar&quot;">​</a></h3><p>Dalam peradaban latihan, hak evolusi bukan hanya hak pembangunan, tetapi juga hak kelangsungan hidup. Kehidupan tingkat rendah, ketika menghadapi berbagai bahaya di kosmos (seperti fluktuasi bidang, badai energi, invasi ras asing, dll.), memiliki probabilitas kelangsungan hidup yang jauh lebih rendah daripada kehidupan tingkat tinggi. Oleh karena itu, memastikan setiap kehidupan memiliki jalur evolusi, pada dasarnya adalah memastikan hak kelangsungan hidup dasar setiap kehidupan.</p><h3 id="_2-2-perbedaan-bakat-awal-tidak-seharusnya-menentukan-nasib-evolusi" tabindex="-1">2.2 Perbedaan bakat awal tidak seharusnya menentukan nasib evolusi <a class="header-anchor" href="#_2-2-perbedaan-bakat-awal-tidak-seharusnya-menentukan-nasib-evolusi" aria-label="Permalink to &quot;2.2 Perbedaan bakat awal tidak seharusnya menentukan nasib evolusi&quot;">​</a></h3><p>Setiap kehidupan memiliki perbedaan besar dalam bakat awalnya (bakat ras, latar belakang keluarga, bidang kelahiran, bakat bawaan, dll.). Di era predasionisme, perbedaan ini sering diperbesar menjadi jurang yang tidak dapat dilewati — kehidupan dengan asal-usul baik memonopoli sumber daya berkualitas, sementara kehidupan dengan asal-usul buruk bahkan tidak dapat memperoleh metode latihan dasar. Peradaban simbiosis percaya bahwa perbedaan bakat awal ada secara objektif, tetapi tidak seharusnya menjadi satu-satunya faktor yang menentukan nasib evolusi. Peran institusi adalah untuk mengompensasi perbedaan awal ini, dan memberikan setiap kehidupan kesempatan untuk mengubah nasib melalui usaha yang diperoleh kemudian.</p><h3 id="_2-3-individu-yang-ditinggalkan-adalah-kerugian-potensial-bagi-peradaban" tabindex="-1">2.3 Individu yang ditinggalkan adalah kerugian potensial bagi peradaban <a class="header-anchor" href="#_2-3-individu-yang-ditinggalkan-adalah-kerugian-potensial-bagi-peradaban" aria-label="Permalink to &quot;2.3 Individu yang ditinggalkan adalah kerugian potensial bagi peradaban&quot;">​</a></h3><p>Setiap kehidupan memiliki potensi evolusi, dan seringkali hanya kekurangan jalur dan sumber daya yang cocok. Sebuah kehidupan yang berjuang di lapisan bawah dapat menunjukkan bakat yang mengejutkan setelah memperoleh sistem latihan yang cocok; seorang individu yang dianggap &quot;tidak berguna&quot; mungkin hanya belum menemukan arah evolusi yang cocok untuk dirinya sendiri. Makna sistem jaminan satu jalan untuk semua adalah tidak meninggalkan evolusioner potensial mana pun, dan memperluas sebanyak mungkin bakat peradaban.</p><h3 id="_2-4-evolusi-universal-adalah-dasar-untuk-kenaikan-dimensi-kosmos" tabindex="-1">2.4 Evolusi universal adalah dasar untuk kenaikan dimensi kosmos <a class="header-anchor" href="#_2-4-evolusi-universal-adalah-dasar-untuk-kenaikan-dimensi-kosmos" aria-label="Permalink to &quot;2.4 Evolusi universal adalah dasar untuk kenaikan dimensi kosmos&quot;">​</a></h3><p>Kenaikan dimensi global kosmos tidak dapat hanya bergantung pada beberapa makhluk yang sangat kuat, tetapi memerlukan evolusi universal dari makhluk biasa dari Sepuluh Ribu Ras. Efisiensi jaringan titik jangkar berkorelasi positif dengan jumlah dan kualitas kehidupan yang terhubung ke jaringan. Ketika lebih banyak kehidupan terhubung ke sistem latihan dan meningkatkan tingkat mereka, siklus energi dan operasi hukum dari seluruh jaringan titik jangkar menjadi lebih stabil dan efisien, dan proses kenaikan dimensi kosmos menjadi lebih cepat.</p><h2 id="iii-struktur-hirarkis-sistem-jaminan" tabindex="-1">III. Struktur Hirarkis Sistem Jaminan <a class="header-anchor" href="#iii-struktur-hirarkis-sistem-jaminan" aria-label="Permalink to &quot;III. Struktur Hirarkis Sistem Jaminan&quot;">​</a></h2><p>Sistem jaminan satu jalan untuk semua dibagi menjadi empat tingkat, membentuk rantai jaminan lengkap dari dasar hingga lanjutan:</p><table tabindex="0"><thead><tr><th>Tingkat</th><th>Nama</th><th>Isi Jaminan</th><th>Cakupan</th></tr></thead><tbody><tr><td>Tingkat Pertama</td><td>Jaminan Dasar</td><td>Metode latihan gratis, distribusi sumber daya minimum, layanan medis dan pendidikan dasar</td><td>Semua kehidupan, tanpa hambatan masuk</td></tr><tr><td>Tingkat Kedua</td><td>Dukungan Terarah</td><td>Sumber daya tambahan, mentor, dukungan teknologi untuk kelompok rentan</td><td>Individu dan ras dengan bakat awal lemah</td></tr><tr><td>Tingkat Ketiga</td><td>Perluasan Peluang</td><td>Peluang latihan lanjutan, pertukaran antar-bidang, hak partisipasi dalam proyek khusus</td><td>Kultivator dengan potensi tetapi tanpa sumber daya yang cukup</td></tr><tr><td>Tingkat Keempat</td><td>Insentif Pencapaian</td><td>Sumber daya tingkat tinggi, akses lanjutan titik jangkar, kehormatan peradaban</td><td>Kultivator yang memberikan kontribusi luar biasa</td></tr></tbody></table><p>Tingkat pertama adalah &quot;garis dasar&quot;, memastikan tidak ada yang ditinggalkan; tingkat kedua adalah &quot;kompensasi perbedaan&quot;, mengompensasi perbedaan bakat awal; tingkat ketiga adalah &quot;peningkatan berbakat&quot;, memberikan lebih banyak peluang bagi individu dengan potensi; tingkat keempat adalah &quot;insentif&quot;, menghargai kontributor luar biasa. Keempat tingkat berkembang langkah demi langkah, membentuk sistem jaminan dan insentif yang lengkap.</p><h2 id="iv-isi-spesifik-jaminan-dasar" tabindex="-1">IV. Isi Spesifik Jaminan Dasar <a class="header-anchor" href="#iv-isi-spesifik-jaminan-dasar" aria-label="Permalink to &quot;IV. Isi Spesifik Jaminan Dasar&quot;">​</a></h2><p>Jaminan dasar adalah inti dari sistem satu jalan untuk semua, dan secara spesifik mencakup isi berikut:</p><h3 id="_4-1-jaminan-metode-latihan" tabindex="-1">4.1 Jaminan Metode Latihan <a class="header-anchor" href="#_4-1-jaminan-metode-latihan" aria-label="Permalink to &quot;4.1 Jaminan Metode Latihan&quot;">​</a></h3><p>Metode dasar dari Tiga Ratus Sistem Kultivasi Asal terbuka gratis untuk semua kehidupan, tanpa hambatan masuk apa pun. Setiap kehidupan dapat memilih secara bebas sistem latihan yang cocok untuk dirinya sendiri, tanpa perlu membayar biaya, tanpa perlu bergabung dengan sekte tertentu, tanpa perlu melalui peninjauan kualifikasi. Jaringan titik jangkar memberikan evaluasi kompatibilitas sistem, membantu kultivator menemukan jalur yang paling cocok untuk dirinya sendiri.</p><h3 id="_4-2-jaminan-sumber-daya-latihan" tabindex="-1">4.2 Jaminan Sumber Daya Latihan <a class="header-anchor" href="#_4-2-jaminan-sumber-daya-latihan" aria-label="Permalink to &quot;4.2 Jaminan Sumber Daya Latihan&quot;">​</a></h3><p>Melalui mekanisme kontrak berbasis produksi dan distribusi sumber daya publik, memastikan setiap kehidupan memperoleh sumber daya yang diperlukan untuk mempertahankan latihan dasar. Distribusi sumber daya dasar meliputi: pasokan energi minimum, pil latihan dasar, hak penggunaan peralatan latihan umum. Untuk bidang dengan kelangkaan sumber daya, melakukan distribusi sumber daya antar-bidang melalui jaringan titik jangkar.</p><h3 id="_4-3-jaminan-lingkungan-latihan" tabindex="-1">4.3 Jaminan Lingkungan Latihan <a class="header-anchor" href="#_4-3-jaminan-lingkungan-latihan" aria-label="Permalink to &quot;4.3 Jaminan Lingkungan Latihan&quot;">​</a></h3><p>Peradaban simbiosis telah membangun tempat latihan publik di setiap planet dan bidang, termasuk ruang latihan publik, zona pengaturan konsentrasi energi, ruang persepsi hukum, dll. Tempat-tempat ini terbuka gratis atau dengan harga murah untuk semua kehidupan, memastikan bahkan kultivator termiskin pun memiliki lingkungan latihan yang cocok.</p><h3 id="_4-4-jaminan-bimbingan-mentor" tabindex="-1">4.4 Jaminan Bimbingan Mentor <a class="header-anchor" href="#_4-4-jaminan-bimbingan-mentor" aria-label="Permalink to &quot;4.4 Jaminan Bimbingan Mentor&quot;">​</a></h3><p>Membangun jaringan mentor antar-ras, dan kultivator tingkat lanjut memiliki kewajiban untuk memberikan bimbingan dasar bagi kultivator pemula. Setiap kultivator pemula dapat mengajukan permohonan pencocokan mentor melalui jaringan titik jangkar, mendapatkan jawaban dasar atas pertanyaan dan saran latihan secara gratis. Untuk kultivator dengan kesulitan khusus, memberikan bimbingan terarah satu lawan satu.</p><h3 id="_4-5-jaminan-rehabilitasi-medis" tabindex="-1">4.5 Jaminan Rehabilitasi Medis <a class="header-anchor" href="#_4-5-jaminan-rehabilitasi-medis" aria-label="Permalink to &quot;4.5 Jaminan Rehabilitasi Medis&quot;">​</a></h3><p>Sistem medis simbiosis memberikan layanan medis dasar dan rehabilitasi penyimpangan latihan secara gratis bagi kultivator. Dalam kasus cedera, penyimpangan latihan, gangguan energi, dll. selama proses latihan, dapat memperoleh perawatan dan dukungan rehabilitasi tepat waktu, memastikan kultivator tidak kehilangan kemampuan evolusi karena kecelakaan.</p><h2 id="v-sasaran-dan-metode-dukungan-terarah" tabindex="-1">V. Sasaran dan Metode Dukungan Terarah <a class="header-anchor" href="#v-sasaran-dan-metode-dukungan-terarah" aria-label="Permalink to &quot;V. Sasaran dan Metode Dukungan Terarah&quot;">​</a></h2><p>Dukungan terarah ditujukan untuk kelompok rentan berikut:</p><ul><li><strong>Individu Bakat Rendah</strong>: Individu dengan bakat bawaan lemah dan kemajuan latihan lambat, yang menerima distribusi sumber daya tambahan dan bimbingan yang dipersonalisasi</li><li><strong>Ras Miskin</strong>: Ras dengan kelangkaan sumber daya secara keseluruhan dan tingkat evolusi rendah, yang menerima dukungan terarah dari dana pengembangan ras</li><li><strong>Kelompok Pasca-Bencana</strong>: Kelompok yang kehilangan tempat tinggal dan sumber daya karena bencana bidang, perang, dll., yang menerima bantuan darurat dan dukungan pembangunan kembali</li><li><strong>Kultivator Disabilitas</strong>: Kultivator dengan disabilitas fisik atau mental karena berbagai alasan, yang menerima peralatan bantu latihan khusus dan rencana latihan yang disesuaikan</li><li><strong>Kehidupan Anomali</strong>: Kehidupan anomali yang tidak cocok dengan sistem latihan konvensional, yang menerima evaluasi khusus dan jalur evolusi yang disesuaikan</li></ul><p>Metode dukungan terarah meliputi: distribusi sumber daya tambahan, bimbingan mentor satu lawan satu, rencana latihan yang disesuaikan, penyediaan peralatan khusus, peluang pertukaran antar-bidang, dll. Tujuan dukungan adalah membantu kelompok rentan mencapai tingkat evolusi dasar, dan kemudian secara bertahap beralih ke sistem distribusi normal lebih banyak kerja lebih banyak imbalan.</p><h2 id="vi-sumber-dana-dan-sumber-daya-sistem-jaminan" tabindex="-1">VI. Sumber Dana dan Sumber Daya Sistem Jaminan <a class="header-anchor" href="#vi-sumber-dana-dan-sumber-daya-sistem-jaminan" aria-label="Permalink to &quot;VI. Sumber Dana dan Sumber Daya Sistem Jaminan&quot;">​</a></h2><p>Pengoperasian sistem jaminan satu jalan untuk semua memerlukan banyak sumber daya dan dana, dan sumbernya meliputi:</p><ol><li><strong>Pendapatan Sumber Daya Publik</strong>: Produksi sumber daya seperti urat spiritual publik, urat tambang energi, ladang obat, dll., yang dikelola langsung oleh peradaban simbiosis</li><li><strong>Pajak Regulasi Kontribusi</strong>: Memungut proporsi tertentu dari &quot;pajak regulasi kontribusi&quot; dari kontributor tinggi, digunakan untuk pengoperasian sistem jaminan (tarif progresif, maksimum tidak melebihi 30%)</li><li><strong>Dana Pengembangan Peradaban</strong>: Energi berlebih yang dihasilkan oleh pengoperasian jaringan titik jangkar, sebagian darinya dimasukkan ke dalam dana pengembangan peradaban</li><li><strong>Pendapatan Lisensi Teknologi</strong>: Biaya penggunaan lisensi dari teknologi rekayasa hukum yang dimiliki oleh peradaban simbiosis</li><li><strong>Donasi dan Warisan</strong>: Donasi sukarela dari individu dan ras</li></ol><p>Pendapatan dan pengeluaran sistem jaminan dikelola oleh komite jaminan di bawah Parlemen Republik Sepuluh Ribu Ras, dan akun secara teratur dipublikasikan kepada semua kehidupan dan diawasi.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Sistem jaminan satu jalan untuk semua adalah batu penjuru keadilan sosial Peradaban Simbiosis Jangkar. Ini memastikan bahwa dalam peradaban yang berfokus pada latihan dan evolusi, tidak ada kehidupan yang ditinggalkan oleh sistem evolusi karena asal-usul, bakat, atau kemiskinan. Satu jalan untuk semua tidak berarti mempraktikkan egalitarianisme, tetapi memberikan setiap kehidupan titik awal yang adil, saluran naik, dan janji untuk tidak ditinggalkan. Di bawah jaminan satu jalan untuk semua, setiap kehidupan dapat menemukan jalur evolusinya sendiri.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Prinsip Distribusi Lebih Banyak Kerja Lebih Banyak Imbalan)</li><li>07-自生自长进化法则 (Hukum Evolusi yang Tumbuh Sendiri dan Berkembang Sendiri)</li><li>38-共生医疗体系 (Sistem Medis Simbiosis)</li></ul>',43)])])}const h=n(u,[["render",s]]);export{b as __pageData,h as default};
